import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(HERE, "fixtures") + os.sep
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)
import sys, re
from shots import run, BASE, OUT
results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def as_role(page, role):
    page.get_by_role("button", name="Account menu").click()
    page.get_by_role("menuitem", name=role).click()
    page.wait_for_timeout(400)
def go(page, path, sel="main"):
    page.goto(BASE + path); page.wait_for_selector(sel); page.wait_for_timeout(300)

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main"); side = page.locator("nav[aria-label$=screens]:visible")
    dlg = lambda: page.locator("dialog[open]").last

    # ── Email, laid out like Gmail as in the reference demos (16 Nov, Oisin)
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click()
    page.get_by_role("button", name="Reset demo data").click(); page.wait_for_timeout(400)
    go(page, "/inbox", "main h1")
    rows = main.locator("ul[aria-label^='Inbox emails'] > li")
    panel = page.get_by_role("navigation", name="Folders and labels")
    unread = data(page, "db.mails.filter(m=>m.folder==='Inbox'&&!m.read).length")
    focused = data(page, "db.mails.filter(m=>m.folder==='Inbox'&&!['Supplier statement','General'].includes(m.intent)).length")
    other = data(page, "db.mails.filter(m=>m.folder==='Inbox'&&['Supplier statement','General'].includes(m.intent)).length")
    check("Email: side panel with Compose, Inbox, Starred, Sent, Drafts, Archive and the labels", page.get_by_role("button", name="Compose").count() >= 1 and all(panel.get_by_role("link", name=re.compile(f"^{f}")).count() == 1 for f in ["Inbox", "Starred", "Sent", "Drafts", "Archive"]) and panel.get_by_role("link", name=re.compile("^Enquiry")).count() == 1)
    check("Email: Inbox shows the unread count", panel.get_by_role("link", name=re.compile("^Inbox")).inner_text().strip().endswith(str(unread)) and unread == 5, unread)
    check("Email: Focused holds what someone has to act on, Other the rest", rows.count() == focused and page.get_by_role("tab", name=re.compile("^Other")).inner_text().strip().endswith(str(other)), (rows.count(), focused, other))
    first = rows.first.inner_text()
    check("Email: newest first, grouped under Today, each row with sender, subject, preview, time and label", "Eleanor Prendiville" in first and "Damp in the north gable" in first and "08:50" in first and "Enquiry" in first and main.get_by_role("heading", name="Today").count() == 1)
    rows.first.get_by_role("button", name=re.compile("Eleanor Prendiville")).click(); page.wait_for_timeout(400)
    check("Email: an opened email has its toolbar, the email, the drafted reply and a Summary", main.get_by_role("heading", name="Damp in the north gable at Glebe House").count() == 1 and "1 of" in main.inner_text() and main.get_by_label("Reply", exact=True).count() == 1 and main.get_by_role("complementary", name="Summary").count() == 1 and "Action items" in main.inner_text())
    check("Email: opening it marks it read and the count drops", data(page, "db.mails.find(m=>m.id==='mail-1').read") is True and panel.get_by_role("link", name=re.compile("^Inbox")).inner_text().strip().endswith(str(unread - 1)))
    main.get_by_role("button", name="Label").click(); page.get_by_role("menuitem", name="Quote query").click(); page.wait_for_timeout(200)
    main.get_by_label("Passed to").select_option("p-qs"); page.wait_for_timeout(200)
    check("Email: the label and the person it is passed to can both be changed", data(page, "(() => { const m = db.mails.find(m=>m.id==='mail-1'); return [m.intent, m.routedToId] })()") == ["Quote query", "p-qs"])
    main.get_by_role("button", name="Star", exact=True).click(); page.wait_for_timeout(200)
    check("Email: starring it", data(page, "db.mails.find(m=>m.id==='mail-1').starred") is True)
    main.get_by_role("button", name="Back to Inbox").click(); page.wait_for_timeout(300)
    rows.filter(has_text="Imelda Fahy").get_by_role("button", name=re.compile("Imelda Fahy")).click(); page.wait_for_timeout(300)
    body = main.get_by_label("Reply", exact=True); body.click(); body.press("ControlOrMeta+End"); page.keyboard.type("\nP.S. I have asked for the netting to be checked twice a day.", delay=6); page.wait_for_timeout(200)
    page.screenshot(path=f"{OUT}/160-inbox.png")
    main.get_by_role("button", name="Send reply").click(); page.wait_for_timeout(400)
    st = data(page, "(() => { const sent = db.mails.find(m=>m.folder==='Sent'&&m.subject.startsWith('RE: Dust')); const orig = db.mails.find(m=>m.id==='mail-7'); return [sent.body.endsWith('twice a day.'), sent.fromName, sent.to, orig.folder, !!orig.replyDraft, db.approvals.find(a=>a.id==='ap-7').status] })()")
    check("Email: sending posts the edited reply, archives the email and closes its approval", st == [True, "Aidan King", "Imelda Fahy", "Archive", False, "Approved"] and rows.count() == focused - 1, st)
    page.get_by_role("tab", name=re.compile("^Other")).click(); page.wait_for_timeout(200)
    rows.filter(has_text="Stephen Aylward").get_by_role("button", name=re.compile("Stephen Aylward")).click(); page.wait_for_timeout(300)
    main.get_by_role("button", name="Discard").click(); page.wait_for_timeout(200)
    check("Email: a draft can be discarded and the email stays, with Reply to start again", main.get_by_label("Reply", exact=True).count() == 0 and main.get_by_role("button", name="Reply").count() == 1 and data(page, "db.mails.find(m=>m.id==='mail-10').folder") == "Inbox")
    main.get_by_role("button", name="Archive", exact=True).click(); page.wait_for_timeout(300)
    check("Email: archived from the toolbar", data(page, "db.mails.find(m=>m.id==='mail-10').folder") == "Archive")
    page.get_by_role("tab", name=re.compile("^Focused")).click(); page.wait_for_timeout(200)
    rows.nth(0).get_by_role("checkbox").check(); rows.nth(1).get_by_role("checkbox").check(); page.wait_for_timeout(100)
    check("Email: picking rows shows what can be done to them", "2 selected" in main.inner_text())
    main.get_by_role("button", name="Mark as unread").click(); page.wait_for_timeout(200)
    check("Email: marking several unread at once", data(page, "db.mails.filter(m=>['mail-1','mail-2'].includes(m.id)).every(m=>!m.read)"))
    panel.get_by_role("link", name=re.compile("^Starred")).click(); page.wait_for_timeout(300)
    check("Email: Starred gathers starred email from every folder", main.locator("ul[aria-label^='Starred emails'] > li").count() == data(page, "db.mails.filter(m=>m.starred).length") and "Damp in the north gable" in main.inner_text())
    panel.get_by_role("link", name=re.compile("^Drafts")).click(); page.wait_for_timeout(300)
    check("Email: Drafts holds replies written and not sent", main.locator("ul[aria-label^='Drafts emails'] > li").count() == data(page, "db.mails.filter(m=>m.folder!=='Sent'&&m.replyDraft).length"))
    panel.get_by_role("link", name=re.compile("^Sent")).click(); page.wait_for_timeout(300)
    check("Email: Sent shows who each went to, the reply first", "To: Imelda Fahy" in main.locator("ul[aria-label^='Sent emails'] > li").first.inner_text().split("\n")[:3], main.locator("ul[aria-label^='Sent emails'] > li").first.inner_text()[:60])
    main.locator("ul[aria-label^='Sent emails'] > li").first.get_by_role("button", name=re.compile("Imelda")).click(); page.wait_for_timeout(300)
    check("Email: a sent email opens with no reply box", "RE: Dust on Main Street" in main.inner_text() and main.get_by_label("Reply", exact=True).count() == 0 and main.get_by_role("button", name="Send reply").count() == 0)
    panel.get_by_role("link", name=re.compile("^Archive")).click(); page.wait_for_timeout(300)
    main.locator("ul[aria-label^='Archive emails'] > li").filter(has_text="Stephen Aylward").get_by_role("button", name=re.compile("Stephen Aylward")).click(); page.wait_for_timeout(250)
    main.get_by_role("button", name="Move to inbox").click(); page.wait_for_timeout(300)
    check("Email: an archived email can be moved back", data(page, "db.mails.find(m=>m.id==='mail-10').folder") == "Inbox")
    page.get_by_role("button", name="Compose").first.click(); page.wait_for_timeout(300)
    d = dlg(); d.get_by_label("To").fill("Burren Lime and Stone Supplies")
    check("Email: Compose has small Add Cc and Add Bcc buttons under To", d.get_by_role("button", name="Add Cc").count() == 1 and d.get_by_role("button", name="Add Bcc").count() == 1 and d.get_by_label("Cc", exact=True).count() == 0)
    d.get_by_role("button", name="Add Cc").click(); page.wait_for_timeout(150)
    check("Email: Add Cc opens a Cc box and goes", d.get_by_label("Cc", exact=True).count() == 1 and d.get_by_role("button", name="Add Cc").count() == 0 and d.get_by_role("button", name="Add Bcc").count() == 1)
    d.get_by_label("Cc", exact=True).fill("Eoin Brosnan"); d.get_by_label("Subject").fill("Delivery for St Finian's"); d.get_by_label("Message").fill("Please confirm tomorrow morning's load.")
    d.get_by_role("button", name="Send").click(); page.wait_for_timeout(400)
    check("Email: Compose sends from the shared address and files it under Sent, with the Cc", "/inbox/sent" in page.url and "Delivery for St Finian's" in main.inner_text() and data(page, "db.mails.some(m=>m.folder==='Sent'&&m.subject==='Delivery for St Finian\\'s'&&m.to==='Burren Lime and Stone Supplies'&&m.cc==='Eoin Brosnan')"))
    main.locator("ul[aria-label^='Sent emails'] > li").first.get_by_role("button", name=re.compile("Burren Lime")).click(); page.wait_for_timeout(300)
    check("Email: the sent email shows who was copied", "cc Eoin Brosnan" in main.inner_text())

    # Drag and drop onto labels and folders, as in Gmail
    go(page, "/inbox", "main h1")
    src_row = rows.filter(has_text="Eleanor Prendiville")
    src_row.drag_to(panel.get_by_role("link", name=re.compile("^Complaint"))); page.wait_for_timeout(300)
    # 17 Nov: under a label an email leaves the Inbox, as in Gmail (s7_check.py covers the rest).
    check("Email: dragging an email onto a label files it there, out of the inbox", data(page, "(() => { const m = db.mails.find(m=>m.id==='mail-1'); return [m.intent, m.folder] })()") == ["Complaint", "Filed"])
    rows.filter(has_text="Bernard Mulqueen").get_by_role("checkbox").check(); rows.filter(has_text="Susan Kane").get_by_role("checkbox").check()
    rows.filter(has_text="Bernard Mulqueen").drag_to(panel.get_by_role("link", name=re.compile("^Archive"))); page.wait_for_timeout(300)
    check("Email: dragging picked emails moves them all", data(page, "['mail-2','mail-3'].every(id => db.mails.find(m=>m.id===id).folder==='Archive')"))
    rows.filter(has_text="Mindaugas").drag_to(panel.get_by_role("link", name=re.compile("^Starred"))); page.wait_for_timeout(300)
    check("Email: dragging onto Starred stars it", data(page, "db.mails.find(m=>m.id==='mail-4').starred") is True)
    rows.first.get_by_role("checkbox").check(); page.wait_for_timeout(100)
    main.get_by_role("button", name="Move the selected emails to a label").click(); page.get_by_role("menuitem", name="General").click(); page.wait_for_timeout(200)
    check("Email: the Move to menu does the same for picked emails, without dragging", data(page, "db.mails.filter(m=>m.folder==='Filed'&&m.intent==='General').length") == 1)
    go(page, "/inbox/archive", "main h1")
    for name in ["Bernard Mulqueen", "Susan Kane"]:
        main.locator("ul[aria-label^='Archive emails'] > li").filter(has_text=name).drag_to(panel.get_by_role("link", name=re.compile("^Inbox"))); page.wait_for_timeout(300)
    check("Email: dragging onto Inbox moves them back", data(page, "['mail-2','mail-3'].every(id => db.mails.find(m=>m.id===id).folder==='Inbox')"))
    go(page, "/inbox", "main h1")
    main.get_by_label("Search mail").fill("kilcashel"); page.wait_for_timeout(200)
    check("Email: search finds across the inbox, Focused and Other together", rows.count() == 1 and "Kilcashel" in rows.first.inner_text() and "1 found" in main.inner_text())
    main.get_by_label("Search mail").fill("")
    go(page, "/inbox?mail=mail-1", "main h1")
    main.get_by_role("button", name="Discuss in Team chat").click(); page.wait_for_timeout(500)
    check("Email: Discuss in Team chat posts about it in the right channel and opens it", "/chat/ch-office" in page.url and "Damp in the north gable" in main.inner_text())
    as_role(page, "Site manager")
    go(page, "/inbox")
    check("Email: a site manager has no email", "/inbox" not in page.url, page.url)
    as_role(page, "Managing director")

    # ── Client portal
    go(page, "/portal")
    check("Portal: staff see it as a chosen client, with a note that this is the client's view", main.get_by_label("Client to view the portal as").count() == 1 and "This is exactly what Susan Kane sees" in main.inner_text())
    check("Portal: one page that scrolls, quotes first then each project", "Quotes waiting on you" in main.inner_text() and main.get_by_role("heading", name="Ardmullen House").count() == 1 and side.get_by_role("link").count() == 1)
    blk = page.get_by_label("C720 Ardmullen House")
    check("Portal: a project shows progress, the work, photos, documents and invoices", blk.get_by_role("progressbar").get_attribute("aria-valuenow") == data(page, "(() => { const t = db.scopeTasks.filter(t=>t.projectId==='pr-C720'); return String(Math.round(t.filter(x=>x.done).length / t.length * 100)); })()") and all(t in blk.inner_text() for t in ["The work", "Latest photos", "Documents", "Invoices"]))
    check("Portal: nothing internal is shown in the project or the quote", not re.search(r"margin|cost to date|hourly|labour cost|site manager", blk.inner_text() + main.locator("table").first.inner_text(), re.I))
    page.screenshot(path=f"{OUT}/161-portal.png")
    card = main.locator("div", has=page.get_by_role("heading", name=re.compile("^Q-2616"))).last
    main.get_by_role("button", name="Ask a question").first.click(); d = dlg()
    check("Portal: a question cannot be sent empty", d.get_by_role("button", name="Send question").is_disabled())
    d.get_by_label("Your question").fill("Can the arch be done before Christmas?"); d.get_by_role("button", name="Send question").click(); page.wait_for_timeout(300)
    check("Portal: a question goes back to the office against the quote", data(page, "(() => { const q = db.quotes.find(q=>q.ref==='Q-2616'); return [q.status, q.query] })()") == ["Queried", "Can the arch be done before Christmas?"] and "Can the arch be done before Christmas?" in main.inner_text())
    n_proj = data(page, "db.projects.length")
    main.get_by_role("button", name="Accept this quote").first.click(); d = dlg()
    d.get_by_label("Your purchase order number").fill("PO-7741"); d.get_by_role("button", name="Accept quote").click(); page.wait_for_timeout(400)
    acc = data(page, "(() => { const q = db.quotes.find(q=>q.ref==='Q-2616'); const p = db.projects.find(p=>p.quoteId===q.id); return [q.status, q.poNumber, p.code, p.status] })()")
    check("Portal: accepting a quote sets the project up with the purchase order", acc[:2] == ["Accepted", "PO-7741"] and data(page, "db.projects.length") == n_proj + 1 and "Quotes waiting on you" not in main.inner_text() and acc[2] in main.inner_text(), acc)
    main.get_by_label("Client to view the portal as").select_option(label="Rathdoon Select Vestry"); page.wait_for_timeout(300)
    check("Portal: switching client shows only that client's work", main.get_by_role("heading", name="St Finian's Church").count() == 1 and main.get_by_role("heading", name="Ardmullen House").count() == 0 and "Paid" in main.inner_text())
    as_role(page, "Client"); page.wait_for_timeout(300)
    check("Portal: signed in as the client there is no picker, no staff note and no other department", "/portal" in page.url and main.get_by_label("Client to view the portal as").count() == 0 and "This is exactly what" not in main.inner_text() and page.locator("nav[aria-label=Departments] a").count() <= 1, page.url)

    # ── Site phone view
    as_role(page, "Managing director")
    go(page, "/site")
    phone = page.get_by_label("Phone screen")
    # 16 Nov: the phone opens in English, with the operative's own language one tap away.
    check("Site phone: opens in English first, own language one tap away", phone.get_by_role("button", name="Send a photo").count() == 1 and page.get_by_role("tab", name="English").get_attribute("aria-selected") == "true" and page.get_by_role("tablist", name="Language shown").get_by_role("tab").nth(0).inner_text().strip() == "English", page.get_by_role("tab").all_inner_texts())
    main.get_by_label("Operative to view the phone as").select_option(label="Marek Wiśniewski, Polski"); page.wait_for_timeout(300)
    if phone.get_by_role("button", name="Wyślij zdjęcie").count() == 0:
        page.get_by_role("tab", name="Polski").click(); page.wait_for_timeout(250)
    w = phone.bounding_box()["width"]
    check("Site phone: drawn at phone width, one screen with four large buttons", w <= 390 and phone.get_by_role("button", name="Wyślij zdjęcie").count() == 1 and phone.get_by_role("button", name="Zgłoś dodatkową pracę").count() == 1 and phone.get_by_role("button", name="Złóż prośbę").count() == 1 and phone.get_by_role("button", name="Mój tydzień").count() == 1 and min(b.bounding_box()["height"] for b in phone.get_by_role("button").all()[-4:]) >= 56, w)
    check("Site phone: a Polish stonemason sees his site and the instructions in Polish", "C719 St Finian's Church" in phone.inner_text() and "Nabożeństwa w niedzielę" in phone.inner_text() and "Przetłumaczone dla Ciebie" in phone.inner_text() and phone.get_attribute("lang") == "pl")
    check("Site phone: the site manager can be rung with one tap", phone.locator("a[href^='tel:']").count() == 1 and "Zadzwoń" in phone.inner_text())
    phone.get_by_role("button", name="Pokaż oryginał po angielsku").click(); page.wait_for_timeout(200)
    check("Site phone: the English original is one tap away", "Services on Sunday at 10:30" in phone.inner_text() and phone.get_by_role("button", name="Pokaż w moim języku").count() == 1)
    page.screenshot(path=f"{OUT}/162-site-pl.png")
    phone.get_by_role("button", name="Wyślij zdjęcie").click(); d = dlg()
    check("Site phone: a photo needs a picture and a caption", d.get_by_role("button", name="Wyślij").is_disabled() and d.get_by_role("button", name="Take a photo", exact=True).count() == 1)
    d.get_by_label("Choose a photo from this device").set_input_files(FIX + "site-photo.jpg"); page.wait_for_timeout(700)
    d.get_by_label("Co pokazuje zdjęcie?").fill("Wieża, strona zachodnia"); d.get_by_role("button", name="Wyślij").click(); page.wait_for_timeout(400)
    ph = data(page, "(() => { const f = db.files.find(f => f.caption==='Wieża, strona zachodnia'); return [f.projectId, f.addedBy, !!f.dataUrl, db.activity[0].who] })()")
    check("Site phone: the photo lands in the project's photos under the operative's name", ph == ["pr-C719", "Marek Wiśniewski", True, "Marek Wiśniewski"], ph)
    phone.get_by_role("button", name="Zgłoś dodatkową pracę").click(); d = dlg()
    d.get_by_label(re.compile("^Po odkryciu znaleziono zgniłe drewno")).check()
    d.get_by_label("Coś do dodania (opcjonalnie)").fill("Belka nad zakrystią"); d.get_by_role("button", name="Wyślij").click(); page.wait_for_timeout(400)
    v = data(page, "(() => { const v = db.variations[0]; const a = db.approvals.find(a => a.variationId===v.id); return [v.projectId, v.description, v.original, v.originalLanguage, v.status, db.people.find(p=>p.id===v.raisedById).name, a.status, db.projects.find(p=>p.id===v.projectId).invoiceHold] })()")
    check("Site phone: an extra reaches the office in English with the Polish original kept, as a draft for approval", v == ["pr-C719", "Rotten timber found once opened up", "Po odkryciu znaleziono zgniłe drewno. Belka nad zakrystią", "pl", "Draft", "Marek Wiśniewski", "Pending", True], v)
    phone.get_by_role("button", name="Złóż prośbę").click(); d = dlg()
    check("Site phone: a request needs a description", d.get_by_role("button", name="Wyślij").is_disabled())
    d.get_by_label("Opisz").fill("Dwa wiadra do zaprawy"); d.get_by_role("button", name="Wyślij").click(); page.wait_for_timeout(300)
    rq = data(page, "[db.requests[0].projectId, db.requests[0].kind, db.requests[0].requestedBy, db.requests[0].status, db.requests[0].heldBy]")
    # 17 Nov (Oisin): an operative's request goes to the site manager first, not straight to the office.
    check("Site phone: a request goes to the site manager first", rq == ["pr-C719", "own_plant", "Marek Wiśniewski", "Open", "site"] and "kierownika budowy" in page.locator("[aria-live=polite]").last.inner_text(), rq)
    phone.get_by_role("button", name="Mój tydzień").click(); d = dlg()
    check("Site phone: My week lists five days with the site for each", d.locator("li").count() == 5 and d.locator("li", has_text="C719").count() == 5, d.inner_text())
    d.get_by_role("button", name="Close").click()
    page.get_by_role("tab", name="English").click(); page.wait_for_timeout(250)
    check("Site phone: a toggle shows the same screen in English for whoever is demonstrating", phone.get_by_role("button", name="Send a photo").count() == 1 and "Services on Sunday" in phone.inner_text())
    main.get_by_label("Operative to view the phone as").select_option(label="Mindaugas Petrauskas, Lietuvių"); page.wait_for_timeout(300)
    check("Site phone: a Lithuanian roofer gets Lithuanian", "Muziejus lankytojams atviras" in phone.inner_text() and phone.get_by_role("button", name="Siųsti nuotrauką").count() == 1)
    main.get_by_label("Operative to view the phone as").select_option(label="Ionuț Marin, Română"); page.wait_for_timeout(300)
    check("Site phone: a Romanian mason gets Romanian", phone.get_by_role("button", name="Trimite o fotografie").count() == 1 and ("Instanța are ședințe" in phone.inner_text() or "O singură bandă" in phone.inner_text()))
    main.get_by_label("Operative to view the phone as").select_option(label="Thiago Barbosa, Português"); page.wait_for_timeout(300)
    check("Site phone: a Portuguese plasterer gets Portuguese", "A casa está habitada" in phone.inner_text())
    main.get_by_label("Operative to view the phone as").select_option(label="Kevin Shortall, English"); page.wait_for_timeout(300)
    check("Site phone: an English speaker gets English and no language toggle", page.get_by_role("tab", name="English").count() == 0 and phone.get_by_role("button", name="Send a photo").count() == 1)
    page.screenshot(path=f"{OUT}/163-site-en.png")
    as_role(page, "Operative")
    check("Site phone: signed in as an operative there is only the phone view, with no picker", "/site" in page.url and main.get_by_label("Operative to view the phone as").count() == 0 and page.get_by_label("Phone screen").count() == 1, page.url)
    as_role(page, "Managing director")

    # ── Settings: branding, region, about
    go(page, "/settings")
    main.get_by_label("Short name").fill("Hartwell Restoration"); main.get_by_label("Full trading name").fill("Hartwell Restoration Ltd"); page.wait_for_timeout(200)
    check("Branding: the name changes top left straight away", "Hartwell Restoration" in page.locator("header").first.inner_text() and page.title().startswith("Hartwell Restoration"), page.title())
    before = page.evaluate("getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()")
    main.get_by_role("button", name="Brick").click(); page.wait_for_timeout(200)
    after = page.evaluate("getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()")
    check("Branding: picking a colour recolours the whole system", before != after and after.lower() == "#8a4b2a", (before, after))
    main.get_by_label("Or the firm's own colour").fill("#12"); page.wait_for_timeout(200)
    check("Branding: a half-typed colour code says what is wrong and does not break the page", "not a colour code yet" in main.inner_text() and main.get_by_role("button", name="A main button").count() == 1)
    main.get_by_label("Or the firm's own colour").fill("#2F6F5E"); page.wait_for_timeout(200)
    main.get_by_label("Choose a logo from this device").set_input_files(FIX + "card.png"); page.wait_for_timeout(600)
    check("Branding: a logo replaces the name top left", page.locator("header").first.locator("img").count() == 1 and main.get_by_role("button", name="Remove logo").count() == 1)
    page.screenshot(path=f"{OUT}/164-branding.png")
    main.get_by_role("button", name="Remove logo").click(); page.wait_for_timeout(200)
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click(); page.wait_for_timeout(200)
    dlg().get_by_role("button", name="Reset").click(); page.wait_for_timeout(500)
    check("Branding: it survives a reset of the sample data", "Hartwell Restoration" in page.locator("header").first.inner_text())
    go(page, "/sales"); page.locator("section[aria-label='Sent'] a").first.click(); page.wait_for_timeout(400)
    page.get_by_role("tab", name="Client copy").click(); page.wait_for_timeout(300)
    check("Branding: documents carry the new name", "Hartwell Restoration" in main.inner_text())
    go(page, "/settings")
    main.get_by_role("button", name="Back to ABC Construction").click(); page.wait_for_timeout(300)
    check("Branding: one button puts it back", "ABC Construction" in page.locator("header").first.inner_text() and page.evaluate("getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()").lower() == "#4682b4")
    go(page, "/settings/region")
    page.get_by_role("tab", name="United Kingdom").click(); page.wait_for_timeout(200)
    check("Region: switching asks first, because it rebuilds the sample data", "goes back to the starting point" in dlg().inner_text() and data(page, "db.projects.find(p=>p.code==='C720').county") == "Galway")
    dlg().get_by_role("button", name="Switch and rebuild the sample data").click(); page.wait_for_timeout(700)
    uk = data(page, "[db.projects.find(p=>p.code==='C720').county, db.salesInvoices[0].vatPct, /^07\\d{3} \\d{6}$/.test(db.people[5].phone), /^[A-Z]{2}\\d{2} [A-Z]{3}$/.test(db.vehicles[0].reg)]")
    check("Region: the UK sample data has UK counties, VAT, phone numbers and plates", uk == ["Cumbria", 20, True, True], uk)
    go(page, "/projects", "table")
    t = main.inner_text()
    check("Region: projects show pounds and plain UK counties, with no Co.", "£" in t and "€" not in t and "Kilcolgan, Cumbria" in t and "Co. " not in t, t[:300])
    go(page, "/fleet/vehicles/v-1")
    check("Region: the vehicle test is called MOT, and tax road tax", page.get_by_role("heading", name="Road tax, MOT and insurance").count() == 1 and "CVRT" not in page.locator("main").inner_text())
    go(page, "/invoicing/export")
    check("Region: the export uses the UK VAT rate", "20%" in main.inner_text())
    page.screenshot(path=f"{OUT}/165-uk.png")
    go(page, "/settings/region")
    page.get_by_role("tab", name="Xero").click(); page.wait_for_timeout(200)
    page.get_by_role("tab", name="Ireland").click(); page.wait_for_timeout(200); dlg().get_by_role("button", name="Switch and rebuild the sample data").click(); page.wait_for_timeout(700)
    check("Region: switching back restores the Irish data, and the accounts package choice is kept", data(page, "db.projects.find(p=>p.code==='C720').county") == "Galway" and page.get_by_role("tab", name="Xero").get_attribute("aria-selected") == "true")
    page.get_by_role("tab", name="Sage 50").click()
    go(page, "/settings/about")
    check("About: says what the demo is, what is in it and who built it", "sample data held in this browser" in main.inner_text() and "projects" in main.inner_text() and main.get_by_role("link", name="Vardil").get_attribute("target") == "_blank")

    # ── Dark and phone
    page.get_by_role("button", name="Switch to dark mode").click()
    go(page, "/inbox?mail=mail-1"); page.screenshot(path=f"{OUT}/166-inbox-dark.png")
    page.get_by_role("button", name="Switch to light mode").click()
    page.set_viewport_size({"width": 390, "height": 844})
    for path in ["/inbox", "/inbox?mail=mail-1", "/portal", "/site", "/settings", "/settings/region", "/settings/about"]:
        go(page, path)
        check(f"Phone width: page itself does not scroll sideways on {path}", not page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth"))
    go(page, "/site"); page.screenshot(path=f"{OUT}/167-site-on-phone.png")

errs = []
try:
    errs = run(steps)
except Exception as ex:
    print("STOPPED EARLY:", str(ex).split("\n")[0][:400])
for name, ok, detail in results:
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else f"  [{detail[:300]}]"))
print("console problems:", errs)
print(f"{sum(1 for r in results if r[1])}/{len(results)} passed")
